        uses: actions/checkout@v4

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: package-lock.json

      - name: Install root workspace dependencies
        run: npm ci

      - name: Validate Container Apps deployment configuration
        env:
          AZURE_WORKER_CREDENTIALS: ${{ secrets.AZURE_WORKER_CREDENTIALS }}
          AZURE_BACKEND_CONTAINER_RESOURCE_GROUP: ${{ secrets.AZURE_BACKEND_CONTAINER_RESOURCE_GROUP }}
          AZURE_BACKEND_DATABASE_SECRET_URI: ${{ secrets.AZURE_BACKEND_DATABASE_SECRET_URI }}
          AZURE_BACKEND_SUPABASE_SECRET_KEY_SECRET_URI: ${{ secrets.AZURE_BACKEND_SUPABASE_SECRET_KEY_SECRET_URI }}
          AZURE_BACKEND_CORS_ORIGINS: ${{ secrets.AZURE_BACKEND_CORS_ORIGINS }}
          AZURE_BACKEND_SUPABASE_URL: ${{ secrets.AZURE_BACKEND_SUPABASE_URL }}
          AZURE_BACKEND_SUPABASE_PUBLISHABLE_KEY: ${{ secrets.AZURE_BACKEND_SUPABASE_PUBLISHABLE_KEY }}
        run: |
          missing=0
          for name in AZURE_WORKER_CREDENTIALS AZURE_BACKEND_CONTAINER_RESOURCE_GROUP AZURE_BACKEND_DATABASE_SECRET_URI AZURE_BACKEND_SUPABASE_SECRET_KEY_SECRET_URI AZURE_BACKEND_CORS_ORIGINS AZURE_BACKEND_SUPABASE_URL AZURE_BACKEND_SUPABASE_PUBLISHABLE_KEY; do
            if [ -z "${!name}" ]; then
              echo "::error::Required Gitea secret $name is not configured."
              missing=1
            fi
          done
          exit "$missing"

      - name: Verify Docker npm registry connectivity
        run: |
          echo "Checking DNS resolution inside Docker with the runner host network..."
          timeout 30s docker run --rm --network=host node:22-bookworm-slim \
            node -e "require('dns').lookup('registry.npmjs.org', (error, address) => { if (error) { console.error(error); process.exit(1); } console.log('registry.npmjs.org ->', address); })"

          echo "Checking npm registry connectivity inside Docker with the runner host network..."
          timeout 45s docker run --rm --network=host node:22-bookworm-slim \
            npm ping --registry=https://registry.npmjs.org/

          echo "Docker npm registry connectivity verified."

      - name: Install Azure CLI
        run: |
          curl -sL https://aka.ms/InstallAzureCLIDeb | sudo bash
          az version

      - name: Sign in to Azure
        uses: azure/login@v2
        with:
          creds: ${{ secrets.AZURE_WORKER_CREDENTIALS }}

      - name: Apply pending backend database migrations
        env:
          DATABASE_SECRET_URI: ${{ secrets.AZURE_BACKEND_DATABASE_SECRET_URI }}
        run: |
          echo "Applying reviewed backend database migrations before backend activation."
          DATABASE_URL="$(az keyvault secret show --id "$DATABASE_SECRET_URI" --query value --output tsv)"

          if [ -z "$DATABASE_URL" ]; then
            echo "::error::The backend database secret resolved to an empty value."
            exit 1
          fi

          export DATABASE_URL
          npm run db:migrate --workspace=@sport-analytics/backend

      - name: Sign in to Azure Container Registry
        run: az acr login --name "$ACR_NAME"

      - name: Prepare Docker Buildx
        run: |
          docker buildx version

          docker buildx rm -f backend-ci-builder >/dev/null 2>&1 || true

          docker buildx create \
            --name backend-ci-builder \
            --driver docker-container \
            --driver-opt network=host \
            --buildkitd-flags '--allow-insecure-entitlement network.host' \
            --use \
            --bootstrap

          docker buildx inspect

      - name: Verify Buildx npm registry connectivity
        shell: bash
        run: |
          timeout 60s docker buildx build \
            --progress=plain \
            --allow network.host \
            --network=host \
            --file - \
            . <<'EOF'
          FROM node:22-bookworm-slim
          RUN npm ping --registry=https://registry.npmjs.org/
          EOF

      - name: Build immutable backend container image
        shell: bash
        run: |
          set -o pipefail
          build_log="$(mktemp)"
          trap 'rm -f "$build_log"' EXIT

            if ! docker buildx build \
              --progress=plain \
              --allow network.host \
              --network=host \
              --cache-from "type=registry,ref=$ACR_NAME.azurecr.io/sport-analytics-api:buildcache" \
              --cache-to "type=registry,ref=$ACR_NAME.azurecr.io/sport-analytics-api:buildcache,mode=max" \
              --file apps/backend/Dockerfile \
              --tag "$ACR_NAME.azurecr.io/sport-analytics-api:${{ github.sha }}" \
              --load \
              . 2>&1 | tee "$build_log"; then

            if grep -Fq 'Exit handler never called!' "$build_log"; then
              echo '::error::Backend Docker build failed: npm internal crash (Exit handler never called).'
            elif grep -Eqi 'EAI_AGAIN|ENOTFOUND|ECONNREFUSED|ECONNRESET|ETIMEDOUT|fetch failed' "$build_log"; then
              echo '::error::Backend Docker build failed: npm registry or Docker network failure.'
            elif grep -Eqi 'ELIFECYCLE|node-gyp|npm error (path|command|code [1-9][0-9]*)' "$build_log"; then
              echo '::error::Backend Docker build failed: lifecycle-script failure.'
            else
              echo '::error::Backend Docker build failed; inspect the BuildKit output above.'
            fi

            exit 1
          fi

      - name: Smoke check backend container image
        run: >-
          npm run smoke:backend-container --
          "$ACR_NAME.azurecr.io/sport-analytics-api:${{ github.sha }}"

      - name: Push immutable backend image to Azure Container Registry
        run: docker push "$ACR_NAME.azurecr.io/sport-analytics-api:${{ github.sha }}"

      - name: Deploy backend Container Apps revision
        env:
          RESOURCE_GROUP: ${{ secrets.AZURE_BACKEND_CONTAINER_RESOURCE_GROUP }}
          DATABASE_SECRET_URI: ${{ secrets.AZURE_BACKEND_DATABASE_SECRET_URI }}
          SUPABASE_SECRET_KEY_SECRET_URI: ${{ secrets.AZURE_BACKEND_SUPABASE_SECRET_KEY_SECRET_URI }}
          CORS_ORIGINS: ${{ secrets.AZURE_BACKEND_CORS_ORIGINS }}
          SUPABASE_URL: ${{ secrets.AZURE_BACKEND_SUPABASE_URL }}
          SUPABASE_PUBLISHABLE_KEY: ${{ secrets.AZURE_BACKEND_SUPABASE_PUBLISHABLE_KEY }}
        run: >-
          az deployment group create
          --name backend-${{ github.sha }}
          --resource-group "$RESOURCE_GROUP"
          --template-file infra/azure/backend/main.bicep
          --parameters
          containerImage="$ACR_NAME.azurecr.io/sport-analytics-api:${{ github.sha }}"
          databaseSecretUri="$DATABASE_SECRET_URI"
          supabaseSecretKeySecretUri="$SUPABASE_SECRET_KEY_SECRET_URI"
          corsOrigins="$CORS_ORIGINS"
          supabaseUrl="$SUPABASE_URL"
          supabasePublishableKey="$SUPABASE_PUBLISHABLE_KEY"

      - name: Wait for the healthy backend Container Apps revision
        env:
          RESOURCE_GROUP: ${{ secrets.AZURE_BACKEND_CONTAINER_RESOURCE_GROUP }}
        run: |
          EXPECTED_IMAGE="$ACR_NAME.azurecr.io/sport-analytics-api:${{ github.sha }}"

          for attempt in {1..12}; do
            MATCHING_REVISION=$(az containerapp revision list \
              --name "$BACKEND_CONTAINER_APP_NAME" \
              --resource-group "$RESOURCE_GROUP" \
              --query "[?properties.active && properties.healthState=='Healthy' && properties.template.containers[0].image=='$EXPECTED_IMAGE'] | [0].name" \
              -o tsv)

            echo "Backend revision readiness check $attempt/12"

            az containerapp revision list \
              --name "$BACKEND_CONTAINER_APP_NAME" \
              --resource-group "$RESOURCE_GROUP" \
              --query "[?properties.active].{Revision:name,Health:properties.healthState,Image:properties.template.containers[0].image}" \
              -o table
---PREPARE DEPLOY---
import { spawnSync } from 'node:child_process';
import { access, cp, lstat, mkdir, rm, unlink } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const deploymentRoot = path.join(repositoryRoot, '.deployment');
const artifactRoot = path.join(deploymentRoot, 'backend');

const artifactFiles = [
  'package.json',
  'package-lock.json',
  'apps/backend/package.json',
  'apps/backend/certs',
  'apps/backend/dist',
  'packages/contracts/package.json',
  'packages/contracts/dist',
  'packages/batch-processing/package.json',
  'packages/batch-processing/dist',
  'packages/object-storage/package.json',
  'packages/object-storage/dist',
];

async function requireBuildOutput(relativePath) {
  try {
    await access(path.join(repositoryRoot, relativePath));
  } catch {
    throw new Error(`Required build output is missing: ${relativePath}`);
  }
}

async function copyArtifactFile(relativePath) {
  const source = path.join(repositoryRoot, relativePath);
  const destination = path.join(artifactRoot, relativePath);

  await mkdir(path.dirname(destination), { recursive: true });
  await cp(source, destination, { recursive: true });
}

async function replaceWorkspaceLinkWithDirectory(workspaceName, sourceRelativePath) {
  const workspacePath = path.join(artifactRoot, 'node_modules', '@sport-analytics', workspaceName);

  try {
    await unlink(workspacePath);
  } catch (error) {
    if (error?.code !== 'ENOENT') {
      throw error;
    }
  }

  if (sourceRelativePath) {
    await cp(path.join(artifactRoot, sourceRelativePath), workspacePath, {
      recursive: true,
      dereference: true,
    });
  }
}

await requireBuildOutput('apps/backend/dist/index.js');
await requireBuildOutput('packages/contracts/dist/index.js');
await requireBuildOutput('packages/batch-processing/dist/index.js');
await requireBuildOutput('packages/object-storage/dist/index.js');

await rm(artifactRoot, { recursive: true, force: true });
await mkdir(artifactRoot, { recursive: true });

for (const relativePath of artifactFiles) {
  await copyArtifactFile(relativePath);
}

const installArguments = [
  'ci',
  '--omit=dev',
  '--ignore-scripts',
  '--workspace=@sport-analytics/backend',
  '--workspace=@sport-analytics/contracts',
  '--workspace=@sport-analytics/batch-processing',
  '--workspace=@sport-analytics/object-storage',
];
const npmCommand = process.platform === 'win32' ? (process.env.ComSpec ?? 'cmd.exe') : 'npm';
const npmArguments =
  process.platform === 'win32'
    ? ['/d', '/s', '/c', 'npm.cmd', ...installArguments]
    : installArguments;
const install = spawnSync(npmCommand, npmArguments, {
  cwd: artifactRoot,
  env: process.env,
  stdio: 'inherit',
});

if (install.error) {
  throw install.error;
}

if (install.status !== 0) {
  throw new Error(`Production dependency installation failed with exit code ${install.status}.`);
}

await replaceWorkspaceLinkWithDirectory('contracts', 'packages/contracts');
await replaceWorkspaceLinkWithDirectory('batch-processing', 'packages/batch-processing');
await replaceWorkspaceLinkWithDirectory('object-storage', 'packages/object-storage');
await replaceWorkspaceLinkWithDirectory('backend');

const installedContracts = path.join(artifactRoot, 'node_modules', '@sport-analytics', 'contracts');
const installedContractsStats = await lstat(installedContracts);

if (!installedContractsStats.isDirectory() || installedContractsStats.isSymbolicLink()) {
  throw new Error('The deployment artifact does not contain a physical contracts package.');
}

await access(path.join(installedContracts, 'dist', 'index.js'));
const installedBatchProcessing = path.join(
  artifactRoot,
  'node_modules',
  '@sport-analytics',
  'batch-processing',
);
const installedBatchProcessingStats = await lstat(installedBatchProcessing);
if (
  !installedBatchProcessingStats.isDirectory() ||
  installedBatchProcessingStats.isSymbolicLink()
) {
  throw new Error('The deployment artifact does not contain a physical batch-processing package.');
}
await access(path.join(installedBatchProcessing, 'dist', 'index.js'));
const installedObjectStorage = path.join(
  artifactRoot,
  'node_modules',
  '@sport-analytics',
  'object-storage',
);
const installedObjectStorageStats = await lstat(installedObjectStorage);
if (!installedObjectStorageStats.isDirectory() || installedObjectStorageStats.isSymbolicLink()) {
  throw new Error('The deployment artifact does not contain a physical object-storage package.');
}
await access(path.join(installedObjectStorage, 'dist', 'index.js'));
await access(path.join(artifactRoot, 'apps', 'backend', 'certs', 'supabase-ca.crt'));
console.log(
  `Backend deployment artifact prepared at ${path.relative(repositoryRoot, artifactRoot)}.`,
);

