import { createHmac } from 'node:crypto';
import type { RequestHandler } from 'express';

import type { AnonymousAccessRepository } from './anonymous-access.repository';
import type { ApiConsumerRepository } from './api-consumer.repository';
import { createConsumerAuthentication } from './consumer-authentication';

export interface AnonymousAccessPolicy {
  sourceLimitPerMinute: number;
  globalLimitPerMinute: number;
  sourceKeySecret: string;
}

const canonicalReadPatterns = [
  /^\/competitions(?:\/[^/]+)?$/,
  /^\/seasons(?:\/[^/]+)?$/,
  /^\/fixtures$/,
  /^\/fixtures\/[^/]+$/,
  /^\/fixtures\/[^/]+\/events$/,
  /^\/fixtures\/[^/]+\/events\/export\.(?:json|csv)$/,
  /^\/fixtures\/[^/]+\/events\/[^/]+$/,
  /^\/fixtures\/[^/]+\/statistics$/,
  /^\/fixtures\/[^/]+\/statistics\/[^/]+$/,
  /^\/fixtures\/[^/]+\/statistics\/[^/]+\/events\/export\.(?:json|csv)$/,
  /^\/competitors(?:\/[^/]+)?$/,
  /^\/participants$/,
  /^\/participants\/[^/]+$/,
  /^\/participants\/[^/]+\/fixtures$/,
  /^\/participants\/[^/]+\/statistics(?:\/[^/]+)?$/,
  /^\/statistics\/leaderboards$/,
] as const;

export function createCanonicalReadAuthentication(
  consumerRepository: ApiConsumerRepository,
  anonymousRepository: AnonymousAccessRepository,
  policy: AnonymousAccessPolicy,
  now: () => Date = () => new Date(),
): RequestHandler {
  const authenticateConsumer = createConsumerAuthentication(consumerRepository, now);

  return (request, response, next) => {
    if (
      request.method !== 'GET' ||
      !canonicalReadPatterns.some((pattern) => pattern.test(request.path))
    ) {
      next();
      return;
    }

    if (request.get('X-API-Key') !== undefined) {
      authenticateConsumer(request, response, next);
      return;
    }

    const sourceAddress = request.ip || request.socket.remoteAddress;
    if (!sourceAddress) {
      unavailable(response);
      return;
    }
    const requestTime = now();
    const sourceKey = createHmac('sha256', policy.sourceKeySecret)
      .update(sourceAddress)
      .digest('hex');

    void anonymousRepository
      .consume({
        sourceKey,
        sourceLimit: policy.sourceLimitPerMinute,
        globalLimit: policy.globalLimitPerMinute,
        at: requestTime,
      })
      .then((usage) => {
        const reset = Math.max(
          1,
          Math.ceil((usage.resetAt.getTime() - requestTime.getTime()) / 1000),
        );
        response.setHeader('RateLimit-Limit', policy.sourceLimitPerMinute);
        response.setHeader(
          'RateLimit-Remaining',
          usage.allowed ? Math.max(0, policy.sourceLimitPerMinute - usage.sourceUsed) : 0,
        );
        response.setHeader('RateLimit-Reset', reset);
        if (!usage.allowed) {
          response.setHeader('Retry-After', reset);
          response.status(429).json({
            error: {
              code: 'RATE_LIMIT_EXCEEDED',
              message: 'Too many anonymous requests. Retry after the current rate-limit window.',
            },
          });
          return;
        }
        next();
      })
      .catch(() => unavailable(response));
  };
}

function unavailable(response: Parameters<RequestHandler>[1]): void {
  response.status(503).json({
    error: {
      code: 'RATE_LIMIT_UNAVAILABLE',
      message: 'Anonymous rate limiting is temporarily unavailable. Please retry shortly.',
    },
  });
}
import type { Pool } from 'pg';

import { executeQuery, getDatabasePool, withTransaction } from '../../database';

export interface AnonymousAccessResult {
  allowed: boolean;
  sourceUsed: number;
  globalUsed: number;
  exceeded: 'source' | 'global' | null;
  resetAt: Date;
}

export interface AnonymousAccessRepository {
  consume(input: {
    sourceKey: string;
    sourceLimit: number;
    globalLimit: number;
    at: Date;
  }): Promise<AnonymousAccessResult>;
}

interface CounterRow {
  requestCount: number;
  windowStart: Date;
}

export function createAnonymousAccessRepository(
  pool: Pool = getDatabasePool(),
): AnonymousAccessRepository {
  return {
    async consume({ sourceKey, sourceLimit, globalLimit, at }) {
      return withTransaction(pool, async (client) => {
        const insertedGlobal = await executeQuery(
          client,
          `INSERT INTO api_anonymous_global_minute_usage (window_start, request_count)
           VALUES (date_trunc('minute', $1::timestamptz), 0)
           ON CONFLICT (window_start) DO NOTHING`,
          [at],
        );
        if (insertedGlobal.rowCount === 1) {
          await executeQuery(
            client,
            `DELETE FROM api_anonymous_source_minute_usage
             WHERE window_start < date_trunc('minute', $1::timestamptz) - INTERVAL '2 days'`,
            [at],
          );
          await executeQuery(
            client,
            `DELETE FROM api_anonymous_global_minute_usage
             WHERE window_start < date_trunc('minute', $1::timestamptz) - INTERVAL '2 days'`,
            [at],
          );
        }

        const global = await executeQuery<CounterRow>(
          client,
          `SELECT request_count AS "requestCount", window_start AS "windowStart"
           FROM api_anonymous_global_minute_usage
           WHERE window_start = date_trunc('minute', $1::timestamptz)
           FOR UPDATE`,
          [at],
        );
        const globalCounter = global.rows[0]!;
        const resetAt = new Date(globalCounter.windowStart.getTime() + 60_000);
        if (globalCounter.requestCount >= globalLimit) {
          return {
            allowed: false,
            sourceUsed: 0,
            globalUsed: globalLimit,
            exceeded: 'global',
            resetAt,
          };
        }

        await executeQuery(
          client,
          `INSERT INTO api_anonymous_source_minute_usage
            (source_key, window_start, request_count)
           VALUES ($1, date_trunc('minute', $2::timestamptz), 0)
           ON CONFLICT (source_key, window_start) DO NOTHING`,
          [sourceKey, at],
        );
        const source = await executeQuery<CounterRow>(
          client,
          `SELECT request_count AS "requestCount", window_start AS "windowStart"
           FROM api_anonymous_source_minute_usage
           WHERE source_key = $1 AND window_start = date_trunc('minute', $2::timestamptz)
           FOR UPDATE`,
          [sourceKey, at],
        );
        const sourceCounter = source.rows[0]!;
        if (sourceCounter.requestCount >= sourceLimit) {
          return {
            allowed: false,
            sourceUsed: sourceLimit,
            globalUsed: globalCounter.requestCount,
            exceeded: 'source',
            resetAt,
          };
        }

        await executeQuery(
          client,
          `UPDATE api_anonymous_global_minute_usage
           SET request_count = request_count + 1
           WHERE window_start = $1`,
          [globalCounter.windowStart],
        );
        await executeQuery(
          client,
          `UPDATE api_anonymous_source_minute_usage
           SET request_count = request_count + 1
           WHERE source_key = $1 AND window_start = $2`,
          [sourceKey, sourceCounter.windowStart],
        );

        return {
          allowed: true,
          sourceUsed: sourceCounter.requestCount + 1,
          globalUsed: globalCounter.requestCount + 1,
          exceeded: null,
          resetAt,
        };
      });
    },
  };
}

export function createLazyAnonymousAccessRepository(): AnonymousAccessRepository {
  let repository: AnonymousAccessRepository | undefined;
  return {
    consume: (...args) =>
      (repository ??= createAnonymousAccessRepository()).consume(...args),
  };
}
import request from 'supertest';
import { describe, expect, test, vi } from 'vitest';

import type { AnonymousAccessRepository } from '../../src/modules/api-consumers/anonymous-access.repository';
import type { ApiConsumerRepository } from '../../src/modules/api-consumers/api-consumer.repository';
import { createTestApp } from '../test-app';

const API_KEY = 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
const resetAt = new Date('2026-09-30T10:01:00.000Z');

function consumerRepository(
  overrides: Partial<ApiConsumerRepository> = {},
): ApiConsumerRepository {
  return {
    issue: vi.fn(),
    list: vi.fn(),
    findOwned: vi.fn(),
    rotate: vi.fn(),
    revoke: vi.fn(),
    findActiveConsumer: vi.fn().mockResolvedValue({
      consumerId: 'consumer-7',
      keyId: 'key-9',
      rateLimitPerMinute: 60,
      dailyQuota: 10_000,
    }),
    consumeRateLimit: vi.fn().mockResolvedValue({ allowed: true, used: 1, resetAt }),
    consumeDailyQuota: vi.fn().mockResolvedValue({ allowed: true, used: 1 }),
    recordUsage: vi.fn().mockResolvedValue(undefined),
    listUsage: vi.fn().mockResolvedValue({ totalRequests: 0, entries: [] }),
    ...overrides,
  };
}

function anonymousRepository(
  overrides: Partial<AnonymousAccessRepository> = {},
): AnonymousAccessRepository {
  return {
    consume: vi.fn().mockResolvedValue({
      allowed: true,
      sourceUsed: 1,
      globalUsed: 1,
      exceeded: null,
      resetAt,
    }),
    ...overrides,
  };
}

function createCanonicalApp(
  consumers: ApiConsumerRepository,
  anonymous: AnonymousAccessRepository,
) {
  return createTestApp(
    undefined,
    {
      async listCompetitions() {
        return { data: [], pagination: { nextCursor: null } };
      },
    } as never,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    undefined,
    consumers,
    undefined,
    undefined,
    undefined,
    anonymous,
  );
}

describe('canonical cricket-resource access', () => {
  test('admits a missing API key under the bounded anonymous policy', async () => {
    const consumers = consumerRepository();
    const anonymous = anonymousRepository();

    const response = await request(createCanonicalApp(consumers, anonymous))
      .get('/api/v1/competitions')
      .expect('RateLimit-Limit', '30')
      .expect('RateLimit-Remaining', '29')
      .expect(200);

    expect(response.headers['x-quota-limit']).toBeUndefined();
    expect(anonymous.consume).toHaveBeenCalledOnce();
    expect(anonymous.consume).toHaveBeenCalledWith(
      expect.objectContaining({
        sourceKey: expect.stringMatching(/^[a-f0-9]{64}$/),
        sourceLimit: 30,
        globalLimit: 600,
      }),
    );
    expect(JSON.stringify(vi.mocked(anonymous.consume).mock.calls)).not.toContain('127.0.0.1');
    expect(consumers.findActiveConsumer).not.toHaveBeenCalled();
  });

  test('uses a valid API key for consumer limits, quota and safe canonical-route telemetry', async () => {
    const consumers = consumerRepository();
    const anonymous = anonymousRepository();

    await request(createCanonicalApp(consumers, anonymous))
      .get('/api/v1/competitions?name=Premier')
      .set('X-API-Key', API_KEY)
      .expect('RateLimit-Limit', '60')
      .expect('X-Quota-Limit', '10000')
      .expect(200);

    expect(anonymous.consume).not.toHaveBeenCalled();
    expect(consumers.findActiveConsumer).toHaveBeenCalledOnce();
    await vi.waitFor(() =>
