  const parsed = parse(source) as unknown;

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error('OpenAPI document is not an object');
  }

  const document = parsed as OpenApiDocument;

  if (typeof document.openapi !== 'string' || !document.openapi.startsWith('3.')) {
    throw new Error('OpenAPI document does not declare a supported OpenAPI version');
  }

  if (typeof document.paths !== 'object' || document.paths === null) {
    throw new Error('OpenAPI document does not contain paths');
  }

  return document;
}

export function ApiExplorerPage() {
  const [reloadToken, setReloadToken] = useState(0);
  const [showPlanned, setShowPlanned] = useState(false);
  const [loadState, setLoadState] = useState<LoadState>({ kind: 'loading' });
  const specificationUrl = openApiSpecificationUrl();

  useEffect(() => {
    const controller = new AbortController();
    let active = true;

    setLoadState({ kind: 'loading' });

    async function loadSpecification() {
      try {
        const response = await fetch(specificationUrl, {
          headers: {
            Accept: 'application/yaml, text/yaml, text/plain',
          },
          cache: 'no-store',
          signal: controller.signal,
        });

        if (!response.ok) {
          throw new Error(`OpenAPI request failed with status ${response.status}`);
        }

        const source = await response.text();
        const document = parseOpenApiDocument(source);

        if (active) {
          setLoadState({
            kind: 'ready',
            document,
            plannedOperations: plannedOperations(document),
          });
        }
      } catch {
        if (!active || controller.signal.aborted) return;
        setLoadState({ kind: 'error' });
      }
    }

    void loadSpecification();

    return () => {
      active = false;
      controller.abort();
    };
  }, [reloadToken, specificationUrl]);

  const swaggerDocument = useMemo(() => {
    if (loadState.kind !== 'ready') return null;
    return implementedExplorerDocument(loadState.document);
  }, [loadState]);

  return (
    <PageLayout
      heading="API Explorer"
      description="Explore the authoritative Sport Analytics OpenAPI contract and try implemented endpoints directly from the browser."
    >
      <section className="api-explorer__intro" aria-labelledby="api-explorer-version">
        <div>
          <p className="eyebrow">Public developer interface</p>
          <h2 id="api-explorer-version">Supported API major version: {API_MAJOR_VERSION}</h2>
          <p>
            Choose the access type that matches your use case before exploring individual operations
            below.
          </p>
        </div>
        <nav className="api-explorer__links" aria-label="API supporting resources">
          <a href="https://sports-analytics-tool.pages.dev/api/overview/">API documentation</a>
          <Link to="/dataset-releases">Dataset downloads</Link>
        </nav>
      </section>

      <section className="api-explorer__access" aria-labelledby="api-access-heading">
        <div className="api-explorer__access-heading">
          <p className="eyebrow">Access and authentication</p>
          <h2 id="api-access-heading">How to access the API</h2>
        </div>
        <div className="api-explorer__access-grid">
          <article className="api-explorer__access-card ui-card">
            <h3>Public API</h3>
            <p>
              Public operations can be used without authentication. They provide browsing and read
              access to published sports data under bounded anonymous rate limits.
            </p>
          </article>

          <article className="api-explorer__access-card ui-card">
            <h3>Identified consumer access</h3>
            <p>
              External integrations use the same canonical resource paths as anonymous readers. A
              valid consumer API key sent in the <code>X-API-Key</code> request header identifies
              the consumer and applies its configured limits, quota and usage accounting.
            </p>
            <p>
              Under the current access model, ask a Stat&apos;sTheGame administrator or project
              administrator for API consumer access. Consumer requests have per-consumer rate limits
              and daily quotas. A supplied malformed, unknown, invalid or revoked key is rejected;
              it never falls back to anonymous access.
            </p>
            <p>
              Keep the issued key in secure secret storage. Never place it in a URL, query string,
              browser bundle or logs.
            </p>
            <a href={CONSUMER_API_DOCUMENTATION_URL}>Consumer API access and key guidance</a>
          </article>

          <article className="api-explorer__access-card ui-card">
            <h3>Application and admin API</h3>
            <p>
              Other authenticated application and administrator operations use the
              application&apos;s bearer authentication and role checks. A consumer API key does not
              grant administrator, submission or batch access.
            </p>
          </article>
        </div>
        <p className="api-explorer__authorize-note">
          In the explorer, use <strong>Authorize</strong> to supply an issued consumer key for
          applicable canonical reads or a bearer credential for application operations.
