  async ({ page }) => {
    await stubOpenApi(page);
    await page.goto('/');

    if ((page.viewportSize()?.width ?? 0) < 900) {
      await page.getByRole('button', { name: 'Menu' }).click();
      await page
        .getByRole('navigation', { name: 'Mobile navigation' })
        .getByRole('link', { name: 'API' })
        .click();
